            sl["cls"] = None
            sl["lastapp"] = -1
            sl["anchor"] = t
            sl["backlog"] = 0
            gap = 0
        else:
            gap = t - sl["lastt"]
        sl["lastt"] = t
        qa = min(15, p["length"] // lq)
        qb = min(15, gap // gq)
        sl["win"].append([qa, qb])
        if len(sl["win"]) > W:
            sl["win"] = sl["win"][-W:]
        sl["backlog"] += 1
        fwd = sl["cls"] if sl["cls"] is not None else fb
        votes[ci][fwd] += 1
        pcount[ci] += 1
        job_id = None
        if len(sl["win"]) < W:
            dec = "warmup"
        else:
            Ti = t - sl["anchor"]; Ci = sl["backlog"]
            pv = prob[edge(te, Ti)][edge(ce, Ci)]
            if p["draw"] >= pv:
                dec = "probability"
            elif credit < rd:
                dec = "tokens"
            elif len(pending) >= pc:
                dec = "queue"
            else:
                dec = "sent"
                credit -= rd
                win = [row[:] for row in sl["win"]]
                logits, pred = cnn(win, mdl)
                jid = nextid; nextid += 1
                lane = 0
                for li in range(1, L):
                    if lanes[li] < lanes[lane]: lane = li
                start = max(t, lanes[lane])
                done = start + svc[pred]
                lanes[lane] = done
                rec = {"id": jid, "packet": idx, "connection": conns[ci]["id"],
                       "slot": s, "generation": sl["gen"], "lane": lane,
                       "start": start, "done": done, "window": win,
                       "logits": logits, "prediction": pred, "status": None}
