                        "generation": sl["gen"], "forward": fwd, "decision": dec,
                        "credit": credit, "job": job_id})
    finish(2*10**12 + 10**7)

    conn_out = []
    preds = []
    for ci in range(len(conns)):
        c = conns[ci]
        v = votes[ci]
