        if pcount[ci] > 0:
            pr = 0
            for k in range(1, C):
                if v[k] > v[pr]: pr = k
        preds.append(pr)
        conn_out.append({"id": c["id"], "split": c["split"], "label": c["label"],
                         "packets": pcount[ci], "votes": v, "prediction": pr})

    reports = {}
    for split in ("dev","eval"):
        conf = [[0]*C for _ in range(C)]
        n = 0
        for ci in range(len(conns)):
            if conns[ci]["split"] == split and pcount[ci] > 0:
