    o[path[-1]] = val

def delp(doc, path):
    o = doc
    for p in path[:-1]: o = o[p]
    del o[path[-1]]

VALUES = [True, False, 1.0, -1.5, "1", None, [], {}, [1], "", 2**80, -(2**80),
