# exhaustive check of the requantize shortcut used in main.py
def fast(z, sh):
    if sh:
        h = 1 << (sh-1)
        if z < 0: z = -((h - z) >> sh)
        else: z = (z + h) >> sh
    return z
def slow(z, sh):
    if sh == 0: return z
    d = 1 << sh
    neg = z < 0
    az = -z if neg else z
    q = az // d
    r = az - q*d
    if 2*r >= d: q += 1
    return -q if neg else q
bad = 0
for sh in range(0, 17):
    for z in range(-5000, 5001):
        if fast(z, sh) != slow(z, sh):
            bad += 1
            if bad < 5: print("MISMATCH", z, sh, fast(z,sh), slow(z,sh))
print("rounding mismatches:", bad)

# also verify max-then-round == round-each-then-max (monotonicity assumption)
import random
r = random.Random(0)
bad2 = 0
for _ in range(20000):
    sh = r.randint(0,16)
    vals = [r.randint(-10**6, 10**6) for _ in range(r.randint(1,12))]
    def clamp(x): return 0 if x < 0 else (127 if x > 127 else x)
    a = clamp(fast(max(vals), sh))
    b = max(clamp(fast(v, sh)) for v in vals)
    if a != b:
        bad2 += 1
        if bad2 < 4: print("MONO MISMATCH", sh, vals, a, b)
print("monotonicity violations:", bad2)
EOF

